test('addLine accepts discountPercent on new line', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[1].discountPercent, 15);
});

test('addLine returns DISCOUNT_INVALID for invalid discount', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;

  const invalidDiscounts = [-1, 100.1, 'invalid', NaN];
  for (const discount of invalidDiscounts) {
    const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3, discountPercent: discount });
    assert.equal(addResult.ok, false, `Expected failure for discount: ${discount}`);
    assert.equal(addResult.error, 'DISCOUNT_INVALID');
  }
});

test('addLine updates discount when adding to existing line', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });

  const invoice = createResult.value;
  const addResult = addLine(invoice, { sku: 'DES-HOUR', qty: 3, discountPercent: 20 });

  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 1);
  assert.equal(addResult.value.lines[0].qty, 8);
  assert.equal(addResult.value.lines[0].discountPercent, 20);
});

test('removeLine removes a line from a draft invoice', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

