  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const issueResult = issueInvoice(invoice, []);

  assert.equal(issueResult.ok, false);
  assert.equal(issueResult.error, 'NOT_DRAFT');
});

test('issueInvoice does not mutate the input invoice', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  const originalStatus = invoice.status;
  assert.equal(invoice.number, undefined);

  const issueResult = issueInvoice(invoice, []);

  assert.equal(issueResult.ok, true);
  assert.equal(invoice.status, originalStatus);
  assert.equal(invoice.number, undefined);
  assert.notEqual(issueResult.value, invoice);
});

